# Partie F · Argumenter (B2), leçons 91 à 115
def L(n, title, obj, scene, dia, ce, voc, gt, gex, gq, grule, co, ant, ee, task, cult=None):
    d = {"n": n, "title": title, "obj": obj, "scene": scene, "dia": dia, "ce": ce, "voc": voc,
         "gram": {"t": gt, "ex": gex, "q": gq, "rule": grule}, "co": co, "ant": ant, "ee": ee, "task": task}
    if cult:
        d["cult"] = cult
    return d

