L(109, "Traditions en mouvement", "Discuter des traditions et de leur évolution en nuançant.", "Débat sur les mariages modernes.",
  [("B", "ແຕ່ກ່ອນ|ງານ|ແຕ່ງງານ|ເຮັດ|ຢູ່|ເຮືອນ|.|ດຽວນີ້|ເຮັດ|ຢູ່|ໂຮງແຮມ|.", "Avant, les mariages se faisaient à la maison. Maintenant, à l'hôtel."),
   ("N", "ມັນ|ສະດວກ|ກວ່າ|ແມ່|.", "C'est plus pratique, maman."),
   ("B", "ແຕ່|ສູນເສຍ|ຄວາມ|ອົບອຸ່ນ|.", "Mais on perd la chaleur."),
   ("C", "ບາງ|ປະເພນີ|ປ່ຽນ|,|ແຕ່|ຄຸນຄ່າ|ຍັງ|ຢູ່|.", "Certaines traditions changent, mais les valeurs restent.")],
  [("Où se font les mariages maintenant ?", "À l'hôtel."), ("Que regrette Mme Boua ?", "La chaleur des mariages à la maison.")],
  [("ປະເພນີ", "tradition"), ("ວັດທະນະທຳ", "culture"), ("ຄຸນຄ່າ", "valeur"), ("ສູນເສຍ", "perdre"), ("ອົບອຸ່ນ", "chaleureux"), ("ທັນສະໄໝ", "moderne"), ("ຮັກສາ", "préserver")],
  "nuancer un jugement culturel", [("ບາງ|…|ປ່ຽນ|,|ແຕ່|…", "certains… changent, mais…"), ("ໃນ|ແງ່|ໜຶ່ງ|…", "d'un côté…")],
  [], "Pour nuancer : ໃນແງ່ໜຶ່ງ… ໃນອີກແງ່ໜຶ່ງ… (d'un côté… de l'autre…), ບາງ (certains), ຍັງ (encore).",
  "les nuances.",
  [("D'un côté…", "ໃນ|ແງ່|ໜຶ່ງ|…"), ("Les valeurs restent.", "ຄຸນຄ່າ|ຍັງ|ຢູ່|."), ("Il faut préserver la culture.", "ຕ້ອງ|ຮັກສາ|ວັດທະນະທຳ|.")],
  ["Écris un texte nuancé de 150 mots sur une tradition qui change."], "Discute avec un natif d'une tradition lao et de son évolution."),
L(110, "Lire un texte long", "Comprendre et résumer un article complet.", "Clara lit un long article avec Noy.",
  [("C", "ບົດຄວາມ|ນີ້|ຍາວ|ຫຼາຍ|.", "Cet article est très long."),
   ("N", "ອ່ານ|ຫົວຂໍ້|ກັບ|ຫຍໍ້|ໜ້າ|ທຳອິດ|ກ່ອນ|.", "Lis d'abord le titre et le premier paragraphe."),
   ("N", "ແລ້ວ|ຊອກ|ຫາ|ຄຳ|ເຊື່ອມ|:|ສະນັ້ນ|,|ແຕ່|,|ນອກຈາກນັ້ນ|.", "Puis cherche les connecteurs : donc, mais, de plus.")],
  [("Quelle méthode conseille Noy ?", "Titre, premier paragraphe, puis les connecteurs.")],
  [("ບົດຄວາມ", "article"), ("ຫຍໍ້|ໜ້າ", "paragraphe"), ("ຄຳ|ເຊື່ອມ", "connecteur"), ("ນອກຈາກນັ້ນ", "de plus"), ("ໂດຍ|ລວມ", "globalement"), ("ໃຈຄວາມ|ສຳຄັນ", "idée principale")],
  "les connecteurs écrits", [("ນອກຈາກນັ້ນ", "de plus"), ("ໃນ|ທາງ|ກົງກັນຂ້າມ", "au contraire"), ("ໂດຍ|ລວມ", "globalement")],
  [], "À l'écrit, les connecteurs organisent le texte : ນອກຈາກນັ້ນ (de plus), ໃນທາງກົງກັນຂ້າມ (au contraire), ດັ່ງນັ້ນ (donc), ໂດຍລວມ (globalement).",
  "la structure du texte.",
  [("De plus…", "ນອກຈາກນັ້ນ|…"), ("L'idée principale est…", "ໃຈຄວາມ|ສຳຄັນ|ແມ່ນ|…"), ("Globalement…", "ໂດຍ|ລວມ|…")],
  ["Résume un article lao de 600 mots en 100 mots."], "Lis un article avec un natif et compare vos résumés."),
L(111, "Écrire un texte argumenté", "Rédiger 300 mots sur un sujet de société.", "Clara écrit pour un blog.",
  [("C", "ຂ້ອຍ|ຈະ|ຂຽນ|ກ່ຽວກັບ|ການ|ຮຽນ|ພາສາ|.", "Je vais écrire sur l'apprentissage des langues."),
   ("N", "ວາງ|ໂຄງ|ກ່ອນ|:|ບົດ|ນຳ|,|ເນື້ອ|ເລື່ອງ|,|ບົດ|ສະຫຼຸບ|.", "Fais un plan d'abord : introduction, développement, conclusion."),
   ("C", "ຂອບໃຈ|.|ຊ່ວຍ|ກວດ|ໃຫ້|ແດ່|ເດີ|.", "Merci. Tu me relis, hein.")],
  [("Quel plan conseille Noy ?", "Introduction, développement, conclusion.")],
  [("ວາງ|ໂຄງ", "faire un plan"), ("ບົດ|ນຳ", "introduction"), ("ເນື້ອ|ເລື່ອງ", "développement, contenu"), ("ບົດ|ສະຫຼຸບ", "conclusion"), ("ກວດ", "vérifier, relire"), ("ບົດ|ຄວາມ", "article, texte")],
  "la structure écrite", [("ບົດ|ນຳ|…|ເນື້ອ|ເລື່ອງ|…|ບົດ|ສະຫຼຸບ", "intro… développement… conclusion")],
  [], "Un texte argumenté lao suit le même plan qu'en français. À l'écrit, on évite les particules orales (ເດີ, ເນາະ) et on préfère les connecteurs écrits.",
  "relis ton texte à voix haute.",
  [("Fais un plan d'abord.", "ວາງ|ໂຄງ|ກ່ອນ|."), ("Tu peux me relire ?", "ຊ່ວຍ|ກວດ|ໃຫ້|ແດ່|ໄດ້|ບໍ|?")],
  ["Écris un texte argumenté de 300 mots."], "Fais corriger ton texte par un natif et réécris-le."),
L(112, "Négocier", "Négocier un accord : proposer, concéder, conclure.", "M. Somsak négocie avec un fournisseur.",
  [("S", "ຖ້າ|ຂ້ອຍ|ສັ່ງ|ຫຼາຍ|ຂຶ້ນ|,|ຫຼຸດ|ລາຄາ|ໄດ້|ບໍ|?", "Si je commande plus, vous pouvez baisser le prix ?"),
   ("X", "ໄດ້|ຫ້າ|ເປີເຊັນ|.", "De 5 %."),
   ("S", "ສິບ|ເປີເຊັນ|ແລ້ວ|ຂ້ອຍ|ຈ່າຍ|ເງິນສົດ|.", "10 % et je paie comptant."),
   ("X", "ພົບ|ກັນ|ເຄິ່ງ|ທາງ|,|ເຈັດ|ເປີເຊັນ|.", "Coupons la poire en deux : 7 %."),
   ("S", "ຕົກລົງ|!", "Marché conclu !")],
  [("Quelle remise est finalement accordée ?", "7 %.")],
  [("ສັ່ງ", "commander"), ("ສະເໜີ", "proposer"), ("ຍອມ", "accepter, céder"), ("ພົບ|ກັນ|ເຄິ່ງ|ທາງ", "couper la poire en deux"), ("ເງິນສົດ", "argent liquide"), ("ຕົກລົງ", "conclure, d'accord"),
   ("ເງື່ອນໄຂ", "condition")],
  "la négociation", [("ຖ້າ|…|ໄດ້|ບໍ|?", "si…, est-ce possible ?"), ("ຂ້ອຍ|ຍອມ|…|ຖ້າ|…", "j'accepte… si…")],
  [], "Négocier : proposition conditionnelle (ຖ້າ…ໄດ້ບໍ), contre-proposition, compromis (ພົບກັນເຄິ່ງທາງ), conclusion (ຕົກລົງ).",
  "les chiffres et les conditions.",
  [("Si je commande plus…", "ຖ້າ|ຂ້ອຍ|ສັ່ງ|ຫຼາຍ|ຂຶ້ນ|…"), ("Coupons la poire en deux.", "ພົບ|ກັນ|ເຄິ່ງ|ທາງ|."), ("Marché conclu !", "ຕົກລົງ|!")],
  ["Écris une négociation de 10 répliques."], "Négocie avec un natif (jeu de rôle commercial)."),
